# ── Fournies : les deux structures que tu viens de construire ──────────────
class File:
    def __init__(self):
        self._elements = []

    def est_vide(self):
        return len(self._elements) == 0

    def taille(self):
        return len(self._elements)

    def enfiler(self, valeur):
        self._elements.append(valeur)

    def premier(self):
        if self.est_vide():
            raise IndexError("file vide")
        return self._elements[0]

    def defiler(self):
        if self.est_vide():
            raise IndexError("file vide")
        return self._elements.pop(0)


class Pile:
    def __init__(self):
        self._elements = []

    def est_vide(self):
        return len(self._elements) == 0

    def taille(self):
        return len(self._elements)

    def empiler(self, valeur):
        self._elements.append(valeur)

    def sommet(self):
        if self.est_vide():
            raise IndexError("pile vide")
        return self._elements[-1]

    def depiler(self):
        if self.est_vide():
            raise IndexError("pile vide")
        return self._elements.pop()


